import{_ as e,o as t,c as r,a4 as o}from"./chunks/framework.CSpBcIj4.js";const u=JSON.parse('{"title":"常見問題","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://eurekaffeine.github.io/sapphire-star-codex/zh-hant/faq/"}],["meta",{"property":"og:url","content":"https://eurekaffeine.github.io/sapphire-star-codex/zh-hant/faq/"}],["meta",{"property":"og:title","content":"常見問題 | Sapphire Star Codex"}],["meta",{"property":"og:description","content":"Monster Hunter reference data and armor builds for Wilds, Rise with Sunbreak, and World with Iceborne."}]]},"headers":[],"relativePath":"zh-hant/faq/index.md","filePath":"zh-hant/faq/index.md"}'),n={name:"zh-hant/faq/index.md"};function i(h,a,l,d,s,p){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="常見問題" tabindex="-1">常見問題 <a class="header-anchor" href="#常見問題" aria-label="Permalink to &quot;常見問題&quot;">​</a></h1><h2 id="支援哪些遊戲" tabindex="-1">支援哪些遊戲？ <a class="header-anchor" href="#支援哪些遊戲" aria-label="Permalink to &quot;支援哪些遊戲？&quot;">​</a></h2><p>支援《Monster Hunter Wilds（荒野）》《Rise＋Sunbreak（崛起＋破曉）》與《World＋Iceborne（世界＋冰原）》。每款遊戲使用獨立資料，在首頁切換遊戲即可查看對應內容。</p><h2 id="現在可以下載嗎" tabindex="-1">現在可以下載嗎？ <a class="header-anchor" href="#現在可以下載嗎" aria-label="Permalink to &quot;現在可以下載嗎？&quot;">​</a></h2><p>目前尚無公開的 App Store、Google Play 或 AppGallery 商店頁面。三個平台的原生應用程式正在開發中。上線後，<a href="./../#download">取得應用程式</a>區域會提供經過確認的商店連結。</p><h2 id="沒有網路能用嗎" tabindex="-1">沒有網路能用嗎？ <a class="header-anchor" href="#沒有網路能用嗎" aria-label="Permalink to &quot;沒有網路能用嗎？&quot;">​</a></h2><p>核心圖鑑資料隨應用程式內建，瀏覽、搜尋、收藏與配裝工具在本地執行。開啟外部資料或下載後續更新需要網路。</p><h2 id="配裝器能做什麼" tabindex="-1">配裝器能做什麼？ <a class="header-anchor" href="#配裝器能做什麼" aria-label="Permalink to &quot;配裝器能做什麼？&quot;">​</a></h2><p>選擇目標技能和等級，固定裝備、排除指定裝備，並搜尋符合條件的組合。可按已有裝飾品數量限制搜尋；崛起還支援已有護石與傀異鍊化防具。結果受遊戲資料與篩選條件限制，配裝器不是傷害計算器。</p><h2 id="支援哪些語言" tabindex="-1">支援哪些語言？ <a class="header-anchor" href="#支援哪些語言" aria-label="Permalink to &quot;支援哪些語言？&quot;">​</a></h2><p>繁體中文、簡體中文、英語與日語。個別缺失翻譯會回退至英語。網站截圖會隨頁面語言切換，應用程式內也能選擇語言。</p><h2 id="這是-capcom-官方應用程式嗎" tabindex="-1">這是 CAPCOM 官方應用程式嗎？ <a class="header-anchor" href="#這是-capcom-官方應用程式嗎" aria-label="Permalink to &quot;這是 CAPCOM 官方應用程式嗎？&quot;">​</a></h2><p>不是。本網站是獨立、非商業粉絲專案的自有網站，應用程式與 CAPCOM 無關聯，亦未獲其認可。Monster Hunter、遊戲美術與資料歸 CAPCOM Co., Ltd. 所有。</p><h2 id="如何幫助專案" tabindex="-1">如何幫助專案？ <a class="header-anchor" href="#如何幫助專案" aria-label="Permalink to &quot;如何幫助專案？&quot;">​</a></h2><p>請參閱<a href="./../others/">關於與支援</a>。資料糾錯時，遊戲名稱、條目名稱、具體數值及可複核來源都很有幫助。</p>',15)])])}const f=e(n,[["render",i]]);export{u as __pageData,f as default};
